package com.spai.portal.task.domain;
import java.time.OffsetDateTime;import javax.persistence.*;
@Entity @Table(name="task_progress_history") public class TaskProgressHistory {@Id private String id;@Column(name="task_id",nullable=false)private String taskId;@Column(name="team_id",nullable=false)private String teamId;@Column(name="old_status")private String oldStatus;@Column(name="new_status",nullable=false)private String newStatus;@Column(name="changed_by")private String changedBy;@Column(name="changed_at",nullable=false)private OffsetDateTime changedAt=OffsetDateTime.now();public void setId(String id){this.id=id;}public void setTaskId(String taskId){this.taskId=taskId;}public void setTeamId(String teamId){this.teamId=teamId;}public void setOldStatus(String oldStatus){this.oldStatus=oldStatus;}public void setNewStatus(String newStatus){this.newStatus=newStatus;}public void setChangedBy(String changedBy){this.changedBy=changedBy;}}
